            "heading": "injection-guard-route-coverage--red-team-phase-8--block-d",
            "content": "The injection-guard (`createInjectionGuard` / `withInjectionGuard`) covers all routes\r\nthat accept user prompts. It respects `INJECTION_GUARD_MODE` (default `warn` = log only;\r\n`block` = returns HTTP 400 `SECURITY_001`)."
