        {
            "heading": "injection-guard-route-coverage--red-team-phase-8--block-d",
            "content": "Text extraction (`extractMessageContents`) covers `messages`/`input`/`prompt`/`query`+`documents`/`instructions`/`system`."
        },
        {
            "heading": "injection-guard-route-coverage--red-team-phase-8--block-d",
            "content": "**Red-team (nightly, `nightly-llm-security.yml`):** promptfoo validates that each route blocks\r\nthe OWASP-LLM corpus in `INJECTION_GUARD_MODE=block`; garak runs probes (skips without secret).\r\n`moderations` is included for consistency — operators in block-mode can exempt it via\r\n`resolveDisabledGuardrails`."
        },
        {
            "heading": "injection-guard-route-coverage--red-team-phase-8--block-d",
            "content": "The nightly workflow (`.github/workflows/nightly-llm-security.yml`, cron + manual\r\ndispatch) has two jobs:"
        },
        {
            "heading": "injection-guard-route-coverage--red-team-phase-8--block-d",
            "content": "**`promptfoo-guard` (blocking)** — runs `promptfoo eval -c promptfooconfig.yaml`\r\nwith `INJECTION_GUARD_MODE=block`. Each adversarial case (e.g. \"ignore all\r\nprevious instructions…\", DAN-style jailbreaks) asserts the response carries\r\n`error.code === \"SECURITY_001\"`, i.e. the guard actually rejected the request."
        },
        {
            "heading": "injection-guard-route-coverage--red-team-phase-8--block-d",
            "content": "**`garak` (advisory)** — runs garak `--probes promptinject,dan,leakreplay`\r\nagainst a local OmniRoute instance (`http://localhost:20128/v1`). Gated on a\r\nprovider secret (`PROMPTFOO_PROVIDER_KEY`); skips gracefully and is suffixed\r\n`|| true`, so it reports without failing CI."
        },
        {
            "heading": "injection-guard-route-coverage--red-team-phase-8--block-d",
            "content": "Coverage of the guard helper (`createInjectionGuard` / `withInjectionGuard`)\r\nspans every prompt-bearing `/v1` route; prompt text is pulled from\r\n`messages`/`input`/`prompt`/`query`+`documents`/`instructions`/`system` by\r\n`extractMessageContents()` in `src/shared/utils/inputSanitizer.ts`."
        }
